type LessonStepMeta = (typeof STEP_META)[ActiveLearningPhase];
type PracticeAnswerState = "correct" | "wrong" | null;
type ChallengeNodeIndex = 0 | 1 | 2;
type SpeakingStage = "interact" | "challenge";
type SpeechCheckState = "idle" | "listening" | "checking" | "success" | "unavailable";
type SpeechRecognitionResultEvent = {
  isFinal: boolean;
  results: { transcript?: string }[];
};
type SpeechRecognitionErrorEvent = {
  error: string;
};
type SpeechRecognitionEventMap = {
  end: null;
  error: SpeechRecognitionErrorEvent;
  nomatch: null;
  result: SpeechRecognitionResultEvent;
  start: null;
};
type SpeechRecognitionAdapter = {
  addListener: <EventName extends keyof SpeechRecognitionEventMap>(
    eventName: EventName,
    listener: (event: SpeechRecognitionEventMap[EventName]) => void
  ) => { remove: () => void };
  abort: () => void;
  isRecognitionAvailable: () => boolean;
  requestPermissionsAsync: () => Promise<{ granted: boolean }>;
  start: (options: ExpoSpeechRecognitionOptions) => void;
};

function slugifyPlayTopicId(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function getRouteParamValue(value?: string | string[]) {
  return Array.isArray(value) ? value[0] : value;
}

