function getPreschoolPlayMode(worldId: string): PreschoolPlayMode {
  if (
    worldId === "preschool-number-village" ||
    worldId === "preschool-pattern-playground" ||
    worldId === "preschool-body-world"
  ) {
    return "build";
  }

  if (
    isSizeConceptWorldId(worldId) ||
    worldId === "preschool-colorful-world"
  ) {
    return "sort";
  }

  if (isQuantityConceptWorldId(worldId)) {
    return "move";
  }

  if (
    worldId === "preschool-animal-adventure" ||
    worldId === "preschool-food-town" ||
    worldId === "preschool-fruit-garden"
  ) {
    return "collect";
  }

  return "match";
}

function getPreschoolPlayPrompt(worldId: string, topicLabel: string) {
  const promptByWorld: Record<string, string> = {
    "preschool-animal-adventure": `Bring ${topicLabel} home.`,
    "preschool-big-small": "Sort the matching size.",
    [KINDERGARTEN_SIZE_WORLD_ID]: "Sort the matching size.",
    "preschool-body-world": `Build with ${topicLabel}.`,
    "preschool-colorful-world": `Sort the ${topicLabel} color.`,
    "preschool-family-world": `Match ${topicLabel} to the house.`,
    "preschool-food-town": `Feed ${topicLabel} to BatiBot.`,
    "preschool-fruit-garden": `Put ${topicLabel} in the basket.`,
    "preschool-more-less": "Move the matching group.",
    [KINDERGARTEN_QUANTITY_WORLD_ID]: "Move the matching group.",
    "preschool-number-village": `Build ${topicLabel} in the frame.`,
    "preschool-pattern-playground": "Build the pattern.",
    "preschool-shape-kingdom": `Fit ${topicLabel} in the puzzle.`,
  };

  return promptByWorld[worldId] ?? `Match ${topicLabel}.`;
}

