function getFloatingCloseRightOffset(screenWidth: number, contentWidth: number) {
  return Math.max(16, (screenWidth - contentWidth) / 2);
}

function getTopicLabel(topic?: CurriculumTopic) {
  const title = topic?.title.replace(/\s+\d+-\d+$/, "") ?? "Topic";
  const introMatch = title.match(/^What\s+(?:is|are)\s+(.+)\?$/i);

  if (!introMatch) {
    return title;
  }

  return introMatch[1].replace(/^(?:a|an|the)\s+/i, "");
}

function getTopicItem(
  topic?: CurriculumTopic,
  gradeLevel?: Parameters<typeof getGradeVocabularyItemByWord>[0]["gradeLevel"]
) {
  if (!topic) {
    return null;
  }

  return getGradeVocabularyItemByWord({
    category: topic.category,
    gradeLevel,
    word: topic.title,
  });
}

function getWorldTopics(world: CurriculumWorld) {
  return world.topics.length ? world.topics : [];
}

function getNextTopicForWorld(
  world: CurriculumWorld,
  currentTopicIndex: number
): CurriculumTopic | null {
  return getWorldTopics(world)[currentTopicIndex + 1] ?? null;
}

function getTopicChoices(
  topic: CurriculumTopic | undefined,
  topics: CurriculumTopic[],
  limit = 4
) {
  if (!topic) {
    return [];
  }

  const selected = [topic];
  const distractors = topics.filter(
    (item) => item.title !== topic?.title && !/^What\s+(is|are)\b/i.test(item.title)
  );
  const choices = [...selected, ...distractors].filter(
    (item, index, items) =>
      items.findIndex(
        (candidate) =>
          getTopicLabel(candidate).trim().toLowerCase() ===
          getTopicLabel(item).trim().toLowerCase()
      ) === index
  );
  const choiceCount = getAllowedChoiceCount(limit);
  const visibleChoices = choices.slice(0, choiceCount);
  const correctCount = visibleChoices.filter(
    (item) => item.title === topic.title
  ).length;

  if (correctCount !== 1) {
    return getStableShuffledItems(
      [topic, ...visibleChoices.filter((item) => item.title !== topic.title)]
        .slice(0, choiceCount),
      `${topic.title}-topic-choices-${choiceCount}`
    );
  }

  return getStableShuffledItems(
    visibleChoices,
    `${topic.title}-topic-choices-${choiceCount}`
  );
}

function normalizeLessonAnswer(value: string) {
  return value.trim().toLowerCase().replace(/[?.!,]/g, "").replace(/\s+/g, " ");
}

function getTopicAnswerIntegrityIssue(topic?: CurriculumTopic) {
  if (!topic?.frameworkStages?.length) {
    return null;
  }

  for (const stage of topic.frameworkStages) {
    if (
      !["TRY", "CHOOSE", "PLAY"].includes(stage.stage) ||
      !stage.choices?.length ||
      (stage.stage === "PLAY" &&
        !["choose", "guidedChoose", "independentChoose"].includes(
          stage.requiredAction ?? ""
        ))
    ) {
      continue;
    }

    const integrity = validateActivityCorrectAnswer({
      choices: stage.choices,
      correctAnswer: stage.correctAnswer,
      correctAssetConcept: stage.correctAssetConcept,
      targetConcept: stage.targetConcept ?? stage.correctAnswer,
    });

    if (!integrity.valid) {
      const repaired = repairChoicesForTarget({
        choiceLimit: stage.choices.length,
        choices: stage.choices,
        correctAnswer: stage.correctAnswer,
        correctAssetConcept: stage.correctAssetConcept,
        distractorPool: topic.frameworkStages
          .flatMap((candidate) => candidate.choices ?? [])
          .filter(Boolean),
        targetConcept: stage.targetConcept ?? stage.correctAnswer,
      });

      if (!repaired.valid) {
        return `${stage.stage}: ${repaired.issues[0]}`;
      }
    }
  }

  return null;
}

function getStableHash(value: string) {
  return value.split("").reduce((hash, character) => {
    return (hash * 31 + character.charCodeAt(0)) >>> 0;
  }, 2166136261);
}

function getStableShuffledItems<T>(items: T[], seed: string) {
  const shuffled = [...items];
  let state = getStableHash(seed);

  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    state = (state * 1664525 + 1013904223) >>> 0;
    const swapIndex = state % (index + 1);
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }

  return shuffled;
}

function getScopedAssetTopic(label: string, worldId: string) {
  const normalized = label.trim();

  if (normalized === "Animals") return "Animal Challenge";
  if (normalized === "Body") return "Body";
  if (normalized === "Family" || normalized === "Family Group") return "Family";
  if (normalized === "Fruits" || normalized === "Fruit Basket") return "Fruit Challenge";
  if (normalized === "Meal" || normalized === "Meal Plate") return "Food Challenge";
  if (normalized === "Rainbow") return "Rainbow Color Challenge";
  if (normalized === "Shape") return "Shape Challenge";
  if (worldId === "preschool-family-world" && normalized === "Tree") return "Tree";
  return normalized;
}

function getScopedAssetRequestForLabel(
  label: string,
  worldId: string,
  stage: FrameworkStageLabel
) {
  const topic = getScopedAssetTopic(label, worldId);
  const normalized = normalizeLessonAnswer(topic);
  const crossWorldByLabel: Record<string, string> = {
    apple: "preschool-fruit-garden",
    banana: "preschool-fruit-garden",
    bird: "preschool-animal-adventure",
    bread: "preschool-food-town",
    cat: "preschool-animal-adventure",
    circle: "preschool-shape-kingdom",
    cow: "preschool-animal-adventure",
    dog: "preschool-animal-adventure",
    egg: "preschool-food-town",
    fish: "preschool-animal-adventure",
    grapes: "preschool-fruit-garden",
    juice: "preschool-food-town",
    mango: "preschool-fruit-garden",
    milk: "preschool-food-town",
    orange: "preschool-fruit-garden",
    rectangle: "preschool-shape-kingdom",
    rice: "preschool-food-town",
    square: "preschool-shape-kingdom",
    star: "preschool-shape-kingdom",
    toy: "",
    tree: "",
    triangle: "preschool-shape-kingdom",
    watermelon: "preschool-fruit-garden",
  };
  const resolvedWorldId = crossWorldByLabel[normalized] ?? worldId;

  return {
    stage,
    topic,
    worldId: resolvedWorldId || undefined,
  };
}

function getWorldDistractorLabels(worldId: string, targetLabel: string, topics: CurriculumTopic[]) {
  const topicLabels = topics
    .map((candidate) => getTopicLabel(candidate))
    .filter((label) => normalizeLessonAnswer(label) !== normalizeLessonAnswer(targetLabel))
    .filter((label) => !/challenge$/i.test(label));
  const fallbackByWorld: Record<string, string[]> = {
    "preschool-animal-adventure": ["Cat", "Fish", "Cow", "Toy"],
    "preschool-body-world": ["Hands", "Nose", "Mouth", "Apple"],
    "preschool-colorful-world": ["Blue", "Yellow", "Green", "Black"],
    "preschool-family-world": ["Father", "Sister", "Friend", "Tree"],
    "preschool-food-town": ["Milk", "Bread", "Juice", "Toy"],
    "preschool-fruit-garden": ["Banana", "Mango", "Grapes", "Toy"],
    "preschool-shape-kingdom": ["Square", "Triangle", "Star", "Toy"],
  };

  return uniqueChoiceLabels(
    [...topicLabels, ...(fallbackByWorld[worldId] ?? [])].filter(
      (label) => normalizeLessonAnswer(label) !== normalizeLessonAnswer(targetLabel)
    ),
    5
  );
}

function getRecallPrompt(_worldId: string, _targetLabel: string) {
  return "What did we learn?";
}

function getScopedWordMeaning(worldId: string, targetLabel: string) {
  return getCurriculumMeaning({ topicLabel: targetLabel, worldId });
}

function getReasoningPrompt(worldId: string, targetLabel: string) {
  return getCurriculumMeaning({ topicLabel: targetLabel, worldId });
}

function getAnimalSoundUtterance(targetLabel: string) {
  const soundByAnimal: Record<string, string> = {
    bird: "Tweet tweet!",
    cat: "Meow!",
    cow: "Moo!",
    dog: "Woof woof!",
    fish: "Blub blub!",
    horse: "Neigh!",
  };

  return soundByAnimal[getPreschoolTopicKey(targetLabel)] ?? "";
}

function playAnimalSoundEffect(targetLabel: string) {
  const key = getPreschoolTopicKey(targetLabel);
  const asset = ANIMAL_SOUND_ASSETS[key];

  if (!asset) {
    return false;
  }

  Speech.stop();

  try {
    const player = animalSoundPlayers[key] ?? createAudioPlayer(asset, {
      downloadFirst: true,
      updateInterval: 250,
    });

    animalSoundPlayers[key] = player;
    player.volume = 1;
    void player.seekTo(0)
      .catch(() => undefined)
      .finally(() => player.play());
    return true;
  } catch {
    return false;
  }
}

function getLookSpeech(worldId: string, targetLabel: string) {
  const animalSound = worldId === "preschool-animal-adventure"
    ? getAnimalSoundUtterance(targetLabel)
    : "";

  return animalSound
    ? `This is ${targetLabel}. ${animalSound}`
    : `This is ${targetLabel}.`;
}

function getChoiceFeedbackSpeech(_worldId: string, _correctAnswer: string, correct: boolean) {
  if (!correct) {
    return STANDARD_STAGE_FEEDBACK.wrong;
  }

  return STANDARD_STAGE_FEEDBACK.success;
}

function getTapSuccessSpeech(targetLabel: string, meaningText: string, worldId?: string) {
  const meaning = meaningText.trim();
  const animalSound = worldId === "preschool-animal-adventure"
    ? getAnimalSoundUtterance(targetLabel)
    : "";

  return `${targetLabel}. ${meaning} ${animalSound ? `${animalSound} ` : ""}Great.`;
}

function getReasoningChoices(choices: string[], correctAnswer: string, seed: string) {
  const correct = choices.find((choice) =>
    normalizeLessonAnswer(choice) === normalizeLessonAnswer(correctAnswer)
  ) ?? correctAnswer;
  const distractors = getStableShuffledItems(
    choices.filter((choice) => normalizeLessonAnswer(choice) !== normalizeLessonAnswer(correct)),
    `${seed}-reasoning-distractors`
  ).slice(0, 3);

  return getStableShuffledItems([correct, ...distractors], `${seed}-reasoning`);
}

function getObservationPrompt(worldId: string, targetLabel: string) {
  return "Look carefully.";
}

function PreschoolSearchTapBoard({
  completed,
  mode,
  onComplete,
  promptStyle,
  renderInstructionSpeaker,
  speakText,
  stage,
  targetLabel,
  topic,
  topics,
  world,
}: {
  completed: boolean;
  mode: "look" | "tap";
  onComplete: () => void;
  promptStyle: StyleProp<TextStyle>;
  renderInstructionSpeaker: (text: string, label?: string) => ReactNode;
  speakText: (text: string) => void;
  stage: FrameworkStageLabel;
  targetLabel: string;
  topic: CurriculumTopic;
  topics: CurriculumTopic[];
  world: CurriculumWorld;
}) {
  const [feedback, setFeedback] = useState("");
  const [hintVisible, setHintVisible] = useState(false);
  const [selectedLabel, setSelectedLabel] = useState<string | null>(null);
  const [wrongLabel, setWrongLabel] = useState<string | null>(null);
  const [wrongTrigger, setWrongTrigger] = useState(0);
  const prompt = mode === "look"
    ? getObservationPrompt(world.id, targetLabel)
    : `Tap ${targetLabel}.`;
  const meaningText = getReasoningPrompt(world.id, targetLabel);
  const labels = useMemo(() => {
    const distractors = getWorldDistractorLabels(world.id, targetLabel, topics);

    return getStableShuffledItems(
      uniqueChoiceLabels([targetLabel, ...distractors], 4),
      `${world.id}-${topic.title}-${stage}-${targetLabel}`
    );
  }, [stage, targetLabel, topic.title, topics, world.id]);
  const tapLabels = useMemo(() => {
    const distractors = labels.filter(
      (label) => normalizeLessonAnswer(label) !== normalizeLessonAnswer(targetLabel)
    );
    const repaired = repairChoicesForTarget({
      choiceLimit: 2,
      choices: [targetLabel, ...distractors],
      correctAnswer: targetLabel,
      distractorPool: distractors,
      targetConcept: targetLabel,
    });

    return (repaired.activity.choices ?? [])
      .map((choice) =>
        typeof choice === "string"
          ? choice
          : choice.label ?? choice.text ?? choice.title ?? choice.concept ?? choice.id ?? ""
      )
      .slice(0, 2);
  }, [labels, targetLabel]);

  useEffect(() => {
    setFeedback("");
    setHintVisible(false);
    setSelectedLabel(null);
    setWrongLabel(null);
    setWrongTrigger(0);
  }, [mode, stage, targetLabel, topic.title, world.id]);

  useEffect(() => {
    if (mode !== "look" || completed) {
      return undefined;
    }

    const announceTimer = setTimeout(() => {
      if (world.id !== "preschool-animal-adventure" || !playAnimalSoundEffect(targetLabel)) {
        speakText(getLookSpeech(world.id, targetLabel));
      }
    }, 350);
    const glowTimer = setTimeout(() => {
      setHintVisible(true);
      setFeedback(getLookSpeech(world.id, targetLabel));
    }, 2100);
    const completeTimer = setTimeout(() => {
      onComplete();
    }, 4500);

    return () => {
      clearTimeout(announceTimer);
      clearTimeout(glowTimer);
      clearTimeout(completeTimer);
    };
  }, [completed, mode, onComplete, speakText, targetLabel, world.id]);

  if (mode === "look") {
    const relatedLabels = labels.filter(
      (label) => normalizeLessonAnswer(label) !== normalizeLessonAnswer(targetLabel)
    ).slice(0, 3);

    return (
      <View style={lessonStyles.shapeStageBody}>
        <View style={lessonStyles.instructionRow}>
          <Text style={promptStyle}>{prompt}</Text>
          {renderInstructionSpeaker(prompt, "Hear look prompt")}
        </View>
        <View style={lessonStyles.animalHeroCard}>
          <FamilyAssetPanel
            asset={resolveAsset(getScopedAssetRequestForLabel(targetLabel, world.id, "LOOK"))}
            disabled={false}
            hideLabel={false}
            label={targetLabel}
            large
            level=""
            onPress={() => {
              const playedAnimalSound =
                world.id === "preschool-animal-adventure" && playAnimalSoundEffect(targetLabel);
              const feedbackText = playedAnimalSound
                ? getAnimalSoundUtterance(targetLabel)
                : getLookSpeech(world.id, targetLabel);

              if (!playedAnimalSound) {
                speakText(feedbackText);
              }

              setFeedback(feedbackText);
            }}
            selected={hintVisible}
          />
        </View>
        <View style={lessonStyles.familyScopedChoiceRow}>
          {relatedLabels.map((label) => (
            <FamilyAssetPanel
              asset={resolveAsset(getScopedAssetRequestForLabel(label, world.id, "LOOK"))}
              disabled={false}
              hideLabel={false}
              key={label}
              label={label}
              level=""
              onPress={() => {
                if (world.id !== "preschool-animal-adventure" || !playAnimalSoundEffect(label)) {
                  speakText(label);
                }
              }}
              selected={false}
            />
          ))}
        </View>
        {feedback ? <Text style={lessonStyles.familyFeedback}>{feedback}</Text> : null}
      </View>
    );
  }

  return (
    <View style={lessonStyles.shapeStageBody}>
      <View style={lessonStyles.instructionRow}>
        <Text style={promptStyle}>{prompt}</Text>
        {renderInstructionSpeaker(prompt, `Hear ${mode} prompt`)}
      </View>
      <View style={lessonStyles.familyScopedChoiceRow}>
        {tapLabels.map((label) => {
          const correct = normalizeLessonAnswer(label) === normalizeLessonAnswer(targetLabel);

          return (
            <Shakeable key={label} trigger={wrongLabel === label ? wrongTrigger : 0}>
              <FamilyAssetPanel
                asset={resolveAsset(getScopedAssetRequestForLabel(label, world.id, stage))}
                disabled={mode === "tap" ? completed && correct : completed}
                hideLabel={false}
                label={label}
                large
                level=""
                onPress={() => {
                  if (correct) {
                    setSelectedLabel(label);
                    setHintVisible(true);
                    setFeedback(meaningText);
                    if (world.id !== "preschool-animal-adventure" || !playAnimalSoundEffect(targetLabel)) {
                      speakText(getTapSuccessSpeech(targetLabel, meaningText, world.id));
                    }
                    onComplete();
                    return;
                  }

                  setWrongLabel(label);
                  setWrongTrigger((current) => current + 1);
                  setFeedback("Try again.");
                  speakText("Try again.");
                }}
                selected={selectedLabel === label || (hintVisible && correct)}
              />
            </Shakeable>
          );
        })}
      </View>
      {feedback ? <Text style={lessonStyles.familyFeedback}>{feedback}</Text> : null}
    </View>
  );
}

const DEFAULT_PLAY_PASSING_THRESHOLD = 80;

function getEarlyPlayPassingThreshold(worldId?: string | null) {
  if (worldId?.startsWith("preschool-")) {
    return 70;
  }

  if (worldId?.startsWith("kindergarten-")) {
    return 80;
  }

  return DEFAULT_PLAY_PASSING_THRESHOLD;
}

type PlayActivityType = "sort" | "match" | "sequence" | "hunt" | "clock" | "rounds" | "image-word-drag";
type PlayOutcome = {
  correctCount: number;
  failedAttemptNumber?: number;
  message: string;
  passed: boolean;
  remediationRequired?: boolean;
  score: number;
  threshold: number;
  title: string;
  totalCount: number;
};
type PlayAnswerRecord = {
  correct: boolean;
  correctAnswer: string;
  key: string;
  selectedAnswer: string;
};

function shuffleChallengeItems<T>(items: T[], seed: string) {
  return getStableShuffledItems(items, seed);
}

function calculatePlayScore(
  _activityType: PlayActivityType,
  state: { correct: number; incorrect?: number; total: number }
) {
  if (state.total <= 0) {
    return 0;
  }

  return Math.max(0, Math.min(100, Math.round((state.correct / state.total) * 100)));
}

function hasPassedPlay(score: number, threshold = DEFAULT_PLAY_PASSING_THRESHOLD) {
  return score >= threshold;
}

function buildPlayOutcome(
  score: number,
  threshold = DEFAULT_PLAY_PASSING_THRESHOLD,
  correctCount = 0,
  totalCount = 0,
  failedAttemptNumber = 0
): PlayOutcome {
  const passed = hasPassedPlay(score, threshold);
  const remediationRequired = !passed && shouldShowTryAgainSection(failedAttemptNumber);
  const feedbackCopy = getStageFeedbackCopy(
    passed ? "passed" : remediationRequired ? "remediate" : "wrong",
    failedAttemptNumber
  );

  return {
    correctCount,
    failedAttemptNumber: passed ? undefined : failedAttemptNumber,
    message: feedbackCopy.message,
    passed,
    remediationRequired,
    score,
    threshold,
    title: feedbackCopy.title,
    totalCount,
  };
}

function getPlayFailureCopy(failedAttemptNumber = 0) {
  return getStageFeedbackCopy(
    shouldShowTryAgainSection(failedAttemptNumber) ? "remediate" : "wrong",
    failedAttemptNumber
  );
}

function PlayTryAgainPanel({
  onPress,
}: {
  onPress: () => void;
}) {
  return (
    <View style={lessonStyles.playTryAgainPanel}>
      <Text style={lessonStyles.playTryAgainTitle}>Try Again</Text>
      <AnimatedButton
        accessibilityLabel="Try PLAY again"
        pressedScale={1.05}
        style={lessonStyles.playTryAgainButton}
        onPress={onPress}
      >
        <Ionicons name="return-down-back" size={42} color="#FFFFFF" />
      </AnimatedButton>
    </View>
  );
}

function resetPlayAttempt() {
  return {
    answerLog: [] as PlayAnswerRecord[],
    feedback: "",
    firstAttempts: {} as Record<string, boolean>,
    outcome: null as PlayOutcome | null,
    roundIndex: 0,
    selectedClockHour: null as number | null,
    sequenceIndex: 0,
  };
}

function getPlayPassingThreshold(topic?: CurriculumTopic) {
  const thresholdText = topic?.frameworkStages
    ?.flatMap((stage) => stage.masteryConditions ?? [])
    .find((condition) => /\b\d{2,3}\s*%/.test(condition));
  const threshold = thresholdText?.match(/\b(\d{2,3})\s*%/)?.[1];

  return threshold ? Math.max(1, Math.min(100, Number(threshold))) : DEFAULT_PLAY_PASSING_THRESHOLD;
}

function getNumberFromTopicLabel(topicLabel: string) {
  const match = topicLabel.match(/\d+/);

  return match ? Number(match[0]) : null;
}

function getNumberLesson(worldId: string, topicLabel: string): NumberLesson | null {
  const numberFromTopic = getNumberFromTopicLabel(topicLabel);

  if (!numberFromTopic) {
    return null;
  }

  if (worldId === "preschool-number-village") {
    return {
      numeral: `${numberFromTopic}`,
      numberWord: getCountWords(numberFromTopic).at(-1) ?? `${numberFromTopic}`,
      objectEmoji: "🍎",
      quantity: Math.min(numberFromTopic, 10),
      topicLabel,
    };
  }

  if (
    worldId === KINDERGARTEN_NUMBER_WORLD_ID &&
    /^Number\s+\d+/i.test(topicLabel) &&
    numberFromTopic >= 11 &&
    numberFromTopic <= 20
  ) {
    return {
      numeral: `${numberFromTopic}`,
      numberWord: getCountWords(numberFromTopic).at(-1) ?? `${numberFromTopic}`,
      objectEmoji: "🍎",
      quantity: numberFromTopic,
      topicLabel,
    };
  }

  return null;
}

function getCountingLesson(topicLabel: string, worldId: string): CountingLesson | null {
  const topicKey = getPreschoolTopicKey(topicLabel);
  const numberFromTopic = getNumberFromTopicLabel(topicLabel);

  if (worldId === "preschool-number-village" && numberFromTopic) {
    return {
      baseCount: Math.min(numberFromTopic, 10),
      objectEmoji: "★",
      objectLabel: "stars",
      targetNumber: numberFromTopic,
    };
  }

  if (worldId !== "preschool-counting-forest") {
    return null;
  }

  if (topicKey === "count-animals") {
    return { baseCount: 3, objectEmoji: "🐶", objectLabel: "animals", targetNumber: 3 };
  }

  if (topicKey === "count-fruits") {
    return { baseCount: 3, objectEmoji: "🍎", objectLabel: "fruits", targetNumber: 3 };
  }

  if (topicKey === "count-food") {
    return { baseCount: 3, objectEmoji: "🍚", objectLabel: "foods", targetNumber: 3 };
  }

  if (topicKey === "count-shapes") {
    return { baseCount: 3, objectEmoji: "●", objectLabel: "shapes", targetNumber: 3 };
  }

  return { baseCount: 3, objectEmoji: "★", objectLabel: "stars", targetNumber: 3 };
}

