function getCountingForestStageItems(
  lesson: CountingLesson | null,
  topicLabel: string,
  stage: keyof (typeof COUNTING_FOREST_STAGE_ITEM_IDS)[string]
) {
  if (!lesson?.objectItems?.length) {
    return undefined;
  }

  const topicKey = getPreschoolTopicKey(topicLabel);
  const preferredId = COUNTING_FOREST_STAGE_ITEM_IDS[topicKey]?.[stage];
  const preferredItem = lesson.objectItems.find((item) => item.id === preferredId);

  if (preferredItem) {
    return [preferredItem];
  }

  const fallbackIndexes = {
    challengeHowMany: 2,
    challengeTap: 3,
    interactMatch: 1,
    interactTap: 0,
    practice: 1,
  } satisfies Record<keyof (typeof COUNTING_FOREST_STAGE_ITEM_IDS)[string], number>;

  return [lesson.objectItems[fallbackIndexes[stage] % lesson.objectItems.length]];
}

function getCountingVisualLabel(items?: CountingVisualItem[]) {
  return items?.[0]?.label ?? "objects";
}

function getCountingForestDistractorItems(
  lesson: CountingLesson | null,
  targetItems: CountingVisualItem[] | undefined,
  seed: string
) {
  if (!lesson?.objectItems?.length) {
    return undefined;
  }

  const targetIds = new Set(targetItems?.map((item) => item.id) ?? []);
  const distractors = lesson.objectItems.filter((item) => !targetIds.has(item.id));

  return getStableShuffledItems(
    distractors.length ? distractors : lesson.objectItems,
    seed
  ).slice(0, 2);
}

function getCountingForestLesson(topicLabel: string, worldId: string): CountingLesson | null {
  const lesson = getCountingLesson(topicLabel, worldId);

  if (!lesson || worldId !== "preschool-counting-forest") {
    return lesson;
  }

  const topicKey = getPreschoolTopicKey(topicLabel);
  const objectItems = COUNTING_FOREST_LESSON_ITEMS[topicKey];

  if (!objectItems) {
    return lesson;
  }

  return {
    ...lesson,
    countImage: COUNTING_FOREST_ASSETS.numbers.count,
    objectItems,
    subtitle: `Find out how many ${lesson.objectLabel}`,
    title: topicKey === "count-food" ? "Counting Food" : `Counting ${lesson.objectLabel}`,
  };
}

function getCountWords(count: number) {
  return [
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
    "twenty",
  ].slice(0, Math.max(0, Math.min(count, 20)));
}

function getNearbyNumberChoices(answer: number) {
  if (answer <= 1) {
    return [1, 2, 3, 4];
  }

  if (answer >= 20) {
    return [17, 18, 19, 20];
  }

  const choices = [answer - 1, answer, answer + 1, answer + 2];

  return Array.from(new Set(choices));
}

function getTextChoices(
  answer: string,
  choices: string[],
  seed: string,
  limit: number
) {
  const uniqueChoices = Array.from(new Set([answer, ...choices])).slice(
    0,
    getAllowedChoiceCount(limit)
  );

  return getStableShuffledItems(uniqueChoices, seed);
}

function getTwoNumberChoices(answer: number, choices: number[]) {
  const uniqueChoices = Array.from(new Set(choices.includes(answer) ? choices : [answer, ...choices]));
  const distractor = uniqueChoices.find((choice) => choice !== answer);

  if (!distractor) {
    return [answer, answer + 1];
  }

  const allowedChoices = new Set([answer, distractor]);

  return uniqueChoices.filter((choice) => allowedChoices.has(choice));
}

function getGroupChoices(answer: number) {
  return getNearbyNumberChoices(answer).map((count) => ({
    count,
    id: `group-${count}`,
  }));
}

function getNumberWordChoices(answer: number) {
  return getNearbyNumberChoices(answer).map((count) => ({
    count,
    label: getCountWords(count).at(-1) ?? `${count}`,
  }));
}

function getTeenNumberModelLabel(count: number) {
  if (count <= 10) {
    return `${count}`;
  }

  return `10 + ${count - 10} = ${count}`;
}

function usesTopicLessonFlow(world?: CurriculumWorld | null) {
  return !!world?.topics.length && getWorldActivityTemplate(world.id) !== null;
}

function getWorldTopicRewardId(worldId: string, topicTitle: string) {
  return `${worldId}:${topicTitle}`;
}

function getMasteredTopicTitles(
  world: CurriculumWorld,
  masteredTopics: ReturnType<typeof useLearnerProgress>["progress"]["masteredTopics"]
) {
  return getWorldTopics(world)
    .filter((topic) => masteredTopics[getWorldTopicRewardId(world.id, topic.title)])
    .map((topic) => topic.title);
}

function getCompletedTopicTitles(
  world: CurriculumWorld,
  progress: ReturnType<typeof useLearnerProgress>["progress"]
) {
  return getWorldTopics(world)
    .filter((topic) =>
      isLessonTopicCompleteForUnlock(
        progress,
        getWorldTopicRewardId(world.id, topic.title)
      )
    )
    .map((topic) => topic.title);
}

function getWorldProgressStarValue(completedTopicCount: number, totalTopicCount: number) {
  if (totalTopicCount <= 0) {
    return 0;
  }

  const ratio = Math.max(0, Math.min(1, completedTopicCount / totalTopicCount));
  return Math.max(0, Math.min(3, Math.round(ratio * 3 * 2) / 2));
}

function getWorldCompletedTopicCount(
  world: CurriculumWorld,
  progress: ReturnType<typeof useLearnerProgress>["progress"]
) {
  return getWorldTopics(world).filter((topic) =>
    isLessonTopicCompleteForUnlock(
      progress,
      getWorldTopicRewardId(world.id, topic.title)
    )
  ).length;
}

function getUnlockedWorldCount(
  worlds: CurriculumWorld[],
  progress: ReturnType<typeof useLearnerProgress>["progress"]
) {
  let completedWorldCount = 0;

  for (const world of worlds) {
    const topics = getWorldTopics(world);
    const worldComplete =
      topics.length > 0 &&
      topics.every((topic) =>
        isLessonTopicCompleteForUnlock(
          progress,
          getWorldTopicRewardId(world.id, topic.title)
        )
      );

    if (!worldComplete) {
      break;
    }

    completedWorldCount += 1;
  }

  return Math.min(worlds.length, Math.max(1, completedWorldCount + 1));
}

function speakLearnerStageText(text: string) {
  const copy = text.trim();

  if (!copy) {
    return;
  }

  Speech.stop();
  Speech.speak(copy, {
    language: "en",
    pitch: 1.06,
    rate: 0.78,
  });
}

function getStandardStageInstruction({
  step,
  topic,
  topicLabel,
}: {
  step: ActiveLearningPhase;
  topic?: CurriculumTopic;
  topicLabel: string;
}) {
  const frameworkStage = getFrameworkStageForStep(topic, step);
  const frameworkInstruction =
    frameworkStage?.instruction ??
    frameworkStage?.guidedQuestions?.[0]?.prompt ??
    frameworkStage?.independentQuestions?.[0]?.prompt;

  if (frameworkInstruction) {
    return frameworkInstruction;
  }

  if (step === "Discover") {
    return `Look at ${topicLabel}.`;
  }

  if (step === "Explore") {
    return `Tap ${topicLabel}.`;
  }

  if (step === "Interact") {
    return "What did we learn?";
  }

  if (step === "Practice") {
    return `Find ${topicLabel}.`;
  }

  if (step === "Challenge") {
    return "Finish the game.";
  }

  if (step === "Reward") {
    return "Claim your reward.";
  }

  if (step === "Progress") {
    return "See your progress.";
  }

  return `You mastered ${topicLabel}.`;
}

function getScopedStandardStageInstruction({
  baseInstruction,
  step,
  topicLabel,
  worldId,
}: {
  baseInstruction: string;
  step: ActiveLearningPhase;
  topicLabel: string;
  worldId: string;
}) {
  if (worldId.startsWith("grade3-")) {
    return getGrade3ScopedStageInstruction({ baseInstruction, step, topicLabel, worldId });
  }

  const grade2Lesson = getGrade2StageLesson(worldId, topicLabel);

  if (grade2Lesson) {
    if (step === "Discover") {
      return getMeaningfulInstruction(
        grade2Lesson.look.instruction,
        getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId })
      );
    }

    if (step === "Explore") {
      return "Tap each card to learn.";
    }

    if (step === "Interact") {
      return getMeaningfulInstruction(
        grade2Lesson.try.prompt,
        getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId })
      );
    }

    if (step === "Practice") {
      return getMeaningfulInstruction(
        grade2Lesson.choose.prompt,
        getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId })
      );
    }

    if (step === "Challenge") {
      return getMeaningfulInstruction(
        grade2Lesson.play.instruction,
        getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId })
      );
    }

    return getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId });
  }

  if (!isGrade1LessonWorld(worldId)) {
    return baseInstruction;
  }

  if (worldId === "grade1-word-kingdom") {
    const topicConfig = getWordKingdomTopic(topicLabel);
    if (step === "Discover") {
      return getMeaningfulInstruction(
        topicConfig?.stages[0]?.instruction,
        getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId })
      );
    }

    if (step === "Explore") return "Tap each word card to learn.";
    if (step === "Interact") return getMeaningfulInstruction(getGrade1WordTryConfig(topicLabel).hint, "Choose the correct word.");
    if (step === "Practice") return getMeaningfulInstruction(getGrade1WordChooseConfig(topicLabel).instruction, "Find the matching words.");
    if (step === "Challenge") return "Match each word pair.";
  }

  if (worldId === "grade1-reading") {
    const lesson = getGrade1ReadingQuestLesson(topicLabel);
    const storyTopic = /story/i.test(topicLabel);

    if (step === "Discover") return storyTopic ? "Look at the story picture." : "Look and read the words.";
    if (step === "Explore") return storyTopic ? "Tap the story sentence." : "Tap each word card to hear it.";
    if (step === "Interact") return lesson.tryAnswer ? "What did we learn?" : baseInstruction;
    if (step === "Practice") return lesson.choosePrompt;
    if (step === "Challenge") return storyTopic ? "Put the story in order." : "Answer the reading question.";
  }

  return getGrade1To3UniversalStageInstruction({ step, topicLabel, worldId });
}

function getGrade3ScopedStageInstruction({
  baseInstruction,
  step,
  topicLabel,
  worldId,
}: {
  baseInstruction: string;
  step: ActiveLearningPhase;
  topicLabel: string;
  worldId: string;
}) {
  const topicTitle = getChildTopicName(topicLabel);
  const curatedData = getGrade3FoundationalActivityData(worldId, topicLabel);

  if (curatedData) {
    return getGrade3CuratedStageInstruction({
      data: curatedData,
      step,
      worldId,
    });
  }

  const blueprint = getGrade3LiteracyBlueprint(worldId, topicTitle);

  if (step === "Discover") {
    if (worldId === "grade3-context-clue-canyon") return "Look at the clue sentence.";
    if (/reading words/i.test(topicTitle)) return "Look at the word parts.";
    if (/main idea/i.test(topicTitle)) return "Look for the main idea.";
    if (/supporting/i.test(topicTitle)) return "Look for supporting details.";
    if (/sequence/i.test(topicTitle)) return "Look at the event order.";
    if (/cause|effect/i.test(topicTitle)) return "Look at cause and effect.";
    if (/fact|opinion/i.test(topicTitle)) return "Look at fact and opinion.";
    if (worldId === "grade3-story-adventure") return "Look at the story evidence.";
    if (worldId === "grade3-reading") return "Read the short passage.";
  }

  if (step === "Explore") {
    if (worldId === "grade3-context-clue-canyon") return "Tap each clue to learn.";
    if (/reading words/i.test(topicTitle)) return "Tap each word part.";
    if (/sequence/i.test(topicTitle)) return "Tap each event clue.";
    if (/main idea|supporting|cause|effect|fact|opinion/i.test(topicTitle)) {
      return "Tap each evidence card.";
    }
    if (worldId === "grade3-story-adventure") return "Tap each story card.";
    return blueprint?.tapFacts?.length ? "Tap each card to learn." : baseInstruction;
  }

  if (step === "Interact") {
    return getMeaningfulInstruction(
      blueprint?.tryQuestion,
      worldId === "grade3-context-clue-canyon"
        ? "Choose the clue meaning."
        : getGrade3TryFallbackInstruction(worldId, topicTitle)
    );
  }

  if (step === "Practice") {
    return getMeaningfulInstruction(
      blueprint?.chooseQuestion,
      worldId === "grade3-context-clue-canyon"
        ? "Choose the meaning that fits."
        : "Choose the evidence."
    );
  }

  if (step === "Challenge") {
    return getMeaningfulInstruction(
      blueprint?.playInstruction,
      worldId === "grade3-context-clue-canyon"
        ? "Match the clue to its meaning."
        : "Match the evidence to the answer."
    );
  }

  return baseInstruction;
}

function getGrade3CuratedStageInstruction({
  data,
  step,
  worldId,
}: {
  data: AdvancedActivityData;
  step: ActiveLearningPhase;
  worldId: string;
}) {
  const topic = data.rendererLabel.toLowerCase();

  if (step === "Discover") {
    return `Study the ${topic}.`;
  }

  if (step === "Explore") {
    if (worldId === "grade3-number") return "Tap each place-value part.";
    if (worldId === "grade3-multiplication") return "Tap the groups and product.";
    if (worldId === "grade3-division") return "Tap the dividend, divisor, and quotient.";
    if (worldId === "grade3-fractions") return "Tap the equal parts.";
    if (worldId === "grade3-money") return "Tap each peso value.";
    return "Tap each review clue.";
  }

  if (step === "Interact") {
    return getMeaningfulInstruction(data.prompt, "Choose the correct answer.");
  }

  if (step === "Practice") {
    return getMeaningfulInstruction(data.prompt, "Solve the problem.");
  }

  if (step === "Challenge") {
    return getMeaningfulInstruction(data.stageInstruction, "Complete the activity, then tap Done.");
  }

  if (step === "Reward") {
    return "Lesson Complete!";
  }

  if (step === "Progress") {
    return "Check your progress.";
  }

  return `Show what you know about ${topic}.`;
}

function getGrade3TryFallbackInstruction(worldId: string, topicTitle: string) {
  if (/reading words/i.test(topicTitle)) return "Choose the word-part clue.";
  if (/main idea/i.test(topicTitle)) return "Choose the main idea.";
  if (/supporting/i.test(topicTitle)) return "Choose the supporting detail.";
  if (/sequence/i.test(topicTitle)) return "Choose what happened first.";
  if (/cause|effect/i.test(topicTitle)) return "Choose the cause or effect.";
  if (/fact|opinion/i.test(topicTitle)) return "Choose fact or opinion.";
  if (worldId.includes("reading") || worldId.includes("story")) return "Choose from the passage.";

  return "Choose the correct answer.";
}

function isGrade1To3LessonWorld(worldId: string) {
  return worldId.startsWith("grade1-") || worldId.startsWith("grade2-") || worldId.startsWith("grade3-");
}

function isGrade1LessonWorld(worldId: string) {
  return worldId.startsWith("grade1-");
}

function isGrade2LessonWorld(worldId: string) {
  return worldId.startsWith("grade2-");
}

function getMeaningfulInstruction(
  instruction: string | null | undefined,
  fallback: string
) {
  const copy = instruction?.trim();

  if (
    !copy ||
    /^(tap|read|choose|look)$/i.test(copy) ||
    /^choose the best answer\.?$/i.test(copy) ||
    /^we learn/i.test(copy)
  ) {
    return fallback;
  }

  return copy;
}

function getGrade1To3UniversalStageInstruction({
  step,
  topicLabel,
  worldId,
}: {
  step: ActiveLearningPhase;
  topicLabel: string;
  worldId: string;
}) {
  const concept = getShortLearnerLabel(topicLabel).toLowerCase();
  const isReadingWorld =
    worldId.includes("reading") ||
    worldId.includes("story") ||
    worldId.includes("context-clue");
  const isVocabularyWorld = worldId.includes("word") || worldId.includes("vocabulary");
  const isNumberWorld =
    worldId.includes("number") ||
    worldId.includes("place-value") ||
    worldId.includes("math") ||
    worldId.includes("multiplication") ||
    worldId.includes("division");
  const isMeasurementWorld = worldId.includes("measurement");
  const isFractionWorld = worldId.includes("fraction");
  const isMoneyWorld = worldId.includes("money");
  const isShapeWorld = worldId.includes("shape");
  const isTimeWorld = worldId.includes("time");
  const isChallengeTopic = /challenge|review|master/i.test(topicLabel);

  if (step === "Discover") {
    if (isReadingWorld) return "Look at the reading text.";
    if (isVocabularyWorld) return `Look at the ${concept} examples.`;
    if (isNumberWorld) return "Look at the number model.";
    if (isMeasurementWorld) return "Look at the measurement model.";
    if (isFractionWorld) return "Look at the fraction model.";
    if (isMoneyWorld) return "Look at the money model.";
    if (isShapeWorld) return "Look at the shape.";
    if (isTimeWorld) return "Look at the time picture.";
    return `Look at ${concept}.`;
  }

  if (step === "Explore") {
    if (isReadingWorld) return "Tap the text to hear it.";
    if (isVocabularyWorld) return "Tap each word card to learn.";
    if (isNumberWorld) return "Tap each number example.";
    if (isMeasurementWorld) return "Tap each measurement example.";
    if (isFractionWorld) return "Tap each fraction example.";
    if (isMoneyWorld) return "Tap each money example.";
    return "Tap each card to learn.";
  }

  if (step === "Interact") {
    if (isReadingWorld) return "Choose the answer from the text.";
    if (isVocabularyWorld) return "Choose the correct word.";
    if (isNumberWorld) return "Choose the correct number.";
    if (isMeasurementWorld) return "Choose the correct measure.";
    if (isFractionWorld) return "Choose the correct fraction.";
    if (isMoneyWorld) return "Choose the correct money amount.";
    if (isShapeWorld) return "Choose the correct shape.";
    if (isTimeWorld) return "Choose the correct time.";
    return "Choose the correct answer.";
  }

  if (step === "Practice") {
    if (isReadingWorld) return "Find the answer in the text.";
    if (isVocabularyWorld) return "Find the matching words.";
    if (isNumberWorld) return "Choose the number.";
    if (isMeasurementWorld) return "Find the correct measurement.";
    if (isFractionWorld) return "Find the matching fraction.";
    if (isMoneyWorld) return "Find the correct money amount.";
    if (isShapeWorld) return "Find the matching shape.";
    if (isTimeWorld) return "Find the correct time.";
    return "Find the correct answer.";
  }

  if (step === "Challenge") {
    if (worldId === "grade3-number") return "Build the answer, then tap Done.";
    if (worldId === "grade3-multiplication") return "Build the array, then tap Done.";
    if (worldId === "grade3-division") return "Share equally, then tap Done.";
    if (worldId === "grade3-fractions") return "Match the fraction, then tap Done.";
    if (worldId === "grade3-money") return "Count the pesos, then tap Done.";
    if (worldId === "grade3-master") return "Solve the review task, then tap Done.";
    if (isChallengeTopic) return "Complete the activity.";
    if (isReadingWorld) return "Answer the reading question.";
    if (isVocabularyWorld) return "Match each word pair.";
    if (isNumberWorld) return "Complete the math activity.";
    if (isMeasurementWorld) return "Measure and match.";
    if (isFractionWorld) return "Match the fraction.";
    if (isMoneyWorld) return "Count the money.";
    return "Complete the activity.";
  }

  if (step === "Reward") {
    return "Great work! Claim your reward.";
  }

  if (step === "Progress") {
    return "Check your progress.";
  }

  return `Show what you know about ${concept}.`;
}

function getTopicLessonCanContinue({
  challengePassed,
  currentChallengeNodeCorrect,
  currentChallengeNodeComplete,
  currentInteractNodeComplete,
  exploreTapped,
  isAdvancedLesson,
  isGrade1To3Lesson,
  isLastChallengeNode,
  practiceAnswer,
  rewardClaimed,
  step,
}: {
  challengePassed: boolean;
  currentChallengeNodeCorrect: boolean;
  currentChallengeNodeComplete: boolean;
  currentInteractNodeComplete: boolean;
  exploreTapped: boolean;
  isAdvancedLesson: boolean;
  isGrade1To3Lesson: boolean;
  isLastChallengeNode: boolean;
  practiceAnswer: PracticeAnswerState;
  rewardClaimed: boolean;
  step: ActiveLearningPhase;
}) {
  if (isGrade1To3Lesson && (step === "Discover" || step === "Explore" || step === "Reward")) {
    return true;
  }

  if (step === "Discover" || step === "Explore") {
    return exploreTapped;
  }

  if (step === "Interact") {
    return isAdvancedLesson ? practiceAnswer === "correct" : currentInteractNodeComplete;
  }

  if (step === "Practice") {
    return practiceAnswer === "correct";
  }

  if (step === "Challenge") {
    if (isGrade1To3Lesson) {
      return currentChallengeNodeComplete && currentChallengeNodeCorrect;
    }

    return currentChallengeNodeComplete && (!isLastChallengeNode || challengePassed);
  }

  if (step === "Reward") {
    return rewardClaimed;
  }

  return true;
}

function getSpeechGradeForWorld(worldId: string) {
  if (worldId.startsWith("grade1-")) return "grade1";
  if (worldId.startsWith("grade2-")) return "grade2";
  if (worldId.startsWith("grade3-")) return "grade3";

  return undefined;
}

function getStandardStageFeedback({
  canGoNext,
  challengePassed,
  challengeWrongTopic,
  practiceAnswer,
  rewardClaimed,
  suppressIntroFeedback,
  step,
}: {
  canGoNext: boolean;
  challengePassed: boolean;
  challengeWrongTopic: string | null;
  practiceAnswer: PracticeAnswerState;
  rewardClaimed: boolean;
  suppressIntroFeedback: boolean;
  step: ActiveLearningPhase;
}) {
  if (step === "Challenge") {
    if (challengeWrongTopic === "Time" && !challengePassed) {
      return STANDARD_STAGE_FEEDBACK.timeout;
    }

    if (challengeWrongTopic && !challengePassed) {
      return STANDARD_STAGE_FEEDBACK.wrong;
    }

    return challengePassed ? STANDARD_STAGE_FEEDBACK.success : "";
  }

  if (suppressIntroFeedback && (step === "Discover" || step === "Explore")) {
    return "";
  }

  if (step === "Practice" || step === "Interact") {
    if (practiceAnswer === "wrong") {
      return STANDARD_STAGE_FEEDBACK.wrong;
    }

    return practiceAnswer === "correct" ? STANDARD_STAGE_FEEDBACK.success : "";
  }

  if (step === "Reward") {
    return rewardClaimed ? "Great!" : "";
  }

  if ((step === "Discover" || step === "Explore") && canGoNext) {
    return "Great!";
  }

  return "";
}

function getStageActionLabel({
  challengeNodeIndex,
  challengePassed,
  stageNodeCount,
  step,
}: {
  challengeNodeIndex: number;
  challengePassed: boolean;
  stageNodeCount: number;
  step: ActiveLearningPhase;
}): StandardLessonButtonLabel {
  if (step === "Challenge") {
    if (challengeNodeIndex < stageNodeCount - 1) {
      return "Next";
    }

    return challengePassed ? "Reward" : "Next";
  }

  if (step === "Reward" || step === "Progress") {
    return "Done";
  }

  if (step === "Mastery") {
    return "Done";
  }

  return "Next";
}

function getStandardFeedbackType({
  challengePassed,
  challengeWrongTopic,
  playLimitReached,
  practiceAnswer,
  rewardClaimed,
  standardFeedback,
  step,
}: {
  challengePassed: boolean;
  challengeWrongTopic: string | null;
  playLimitReached: boolean;
  practiceAnswer: PracticeAnswerState;
  rewardClaimed: boolean;
  standardFeedback: string;
  step: ActiveLearningPhase;
}): LessonFeedbackType | null {
  if (!standardFeedback) {
    return null;
  }

  if (playLimitReached) {
    return "limit";
  }

  if (step === "Challenge" && challengeWrongTopic === "Time" && !challengePassed) {
    return "timeout";
  }

  if (
    (step === "Challenge" && challengeWrongTopic && !challengePassed) ||
    ((step === "Practice" || step === "Interact") && practiceAnswer === "wrong")
  ) {
    return "wrong";
  }

  if (
    challengePassed ||
    practiceAnswer === "correct" ||
    rewardClaimed ||
    standardFeedback === "Great!"
  ) {
    return "success";
  }

  return null;
}

function toStandardLessonButtonLabel(label: string): StandardLessonButtonLabel {
  return label === "Reward" || label === "Done" ? label : "Next";
}

function normalizeStageType(value: unknown): string {
  return typeof value === "string" && value.trim().length > 0
    ? value.trim().toLowerCase()
    : "unknown";
}

function toLessonStageLabel(label: unknown): LessonStageLabel {
  return label === "LOOK" ||
    label === "TAP" ||
    label === "TRY" ||
    label === "CHOOSE" ||
    label === "PLAY" ||
    label === "CHALLENGE" ||
    label === "REWARD" ||
    label === "PROGRESS" ||
    label === "MASTERY"
    ? label
    : label === "MASTERED"
      ? "MASTERY"
    : "LOOK";
}

function getProgressLevelIcon(percent: number): keyof typeof Ionicons.glyphMap {
  if (percent >= 100) {
    return "checkmark-circle";
  }

  if (percent >= 75) {
    return "rocket";
  }

  if (percent >= 50) {
    return "trending-up";
  }

  if (percent >= 25) {
    return "leaf";
  }

  return "ellipse-outline";
}

