function getWorldIntroItems(assetKey: WorldIntroAssetKey): WorldIntroItem[] {
  return PRESCHOOL_WORLD_INTRO_ASSETS[assetKey].map((item) => ({
    id: item.id,
    image: item.image,
    label: item.label,
  }));
}

function getWorldIntroChallengeItems(items: WorldIntroItem[], seed: string) {
  const itemCount = Math.min(4, Math.max(2, items.length));

  return getStableShuffledItems(items, seed).slice(0, itemCount);
}

function getWorldIntroLesson(worldId: string, topicLabel: string): WorldIntroLesson | null {
  const config = WORLD_INTRO_CONFIG[worldId];

  if (!config || getPreschoolTopicKey(topicLabel) !== config.topicKey) {
    return null;
  }

  const items = getWorldIntroItems(config.assetKey);
  const alternateItems = getWorldIntroItems(config.alternateAssetKey);

  return {
    alternateChallengeItems: getWorldIntroChallengeItems(
      alternateItems,
      `${worldId}-${topicLabel}-intro-alternate-challenge`
    ),
    alternateItems,
    alternateLabel: config.alternateLabel,
    challengeItems: getWorldIntroChallengeItems(
      items,
      `${worldId}-${topicLabel}-intro-challenge`
    ),
    conceptWord: config.conceptWord,
    description: config.description,
    explorePrompt: config.explorePrompt,
    groupLabel: config.groupLabel,
    items,
    title: topicLabel,
  };
}

