function getKindergartenWordTarget(worldId: string, topicLabel: string) {
  const options = getKindergartenWordOptions(worldId);
  const exact = options.find((option) =>
    normalizeLessonAnswer(option.label) === normalizeLessonAnswer(topicLabel) ||
    normalizeLessonAnswer(option.assetTopic) === normalizeLessonAnswer(topicLabel)
  );

  if (exact) {
    return exact;
  }

  const topicTargets: Record<string, Record<string, string>> = {
    "kindergarten-alphabet": {
      "alphabet challenge": "A",
      "beginning sounds": "B",
      "ending sounds": "T",
      "letter sounds": "S",
      "simple word building": "C",
    },
    "kindergarten-community-village": {
      "community challenge": "Teacher",
      "what is community": "Teacher",
    },
    "kindergarten-nature": {
      "animals in nature": "Animals",
      flowers: "Flower",
      "nature challenge": "Sun",
      plants: "Tree",
      trees: "Tree",
      weather: "Rain",
    },
    [KINDERGARTEN_READING_WORLD_ID]: {
      "listening comprehension": getKindergartenReadingTargetLabel("listening comprehension"),
      "reading readiness challenge": getKindergartenReadingTargetLabel("reading readiness challenge"),
      "word recognition": getKindergartenReadingTargetLabel("word recognition"),
    },
    "kindergarten-school": {
      "classroom objects": "Desk",
      paper: "Paper",
      "school challenge": "Bag",
      "school objects": "Bag",
      "school places": "Desk",
      "school routines": "Notebook",
      "school rules": "Chair",
      "what is school": "Bag",
    },
    "kindergarten-shapes": {
      "shape challenge": "Circle",
      "what are shapes": "Circle",
    },
  };
  const mappedLabel = topicTargets[worldId]?.[normalizeLessonAnswer(topicLabel)];

  return options.find((option) =>
    normalizeLessonAnswer(option.label) === normalizeLessonAnswer(mappedLabel ?? "")
  ) ?? options[0] ?? {
    assetTopic: topicLabel,
    label: getChildTopicName(topicLabel),
    meaning: `${getChildTopicName(topicLabel)} helps us learn.`,
    mission: `Use ${getChildTopicName(topicLabel)}.`,
  };
}

function getKindergartenWordChoices(
  worldId: string,
  target: KindergartenWordOption,
  count: 2 | 4,
  seed: string
) {
  const distractors = getStableShuffledItems(
    getKindergartenWordOptions(worldId).filter(
      (option) => normalizeLessonAnswer(option.label) !== normalizeLessonAnswer(target.label)
    ),
    `${seed}-distractors`
  );
  const uniqueChoices = uniqueKindergartenWordOptions(
    [target, ...distractors],
    count
  );

  return getStableShuffledItems(uniqueChoices, seed);
}

function uniqueKindergartenWordOptions(
  options: KindergartenWordOption[],
  limit: number
) {
  const seen = new Set<string>();
  const unique: KindergartenWordOption[] = [];

  for (const option of options) {
    const key = normalizeLessonAnswer(option.label);

    if (!key || seen.has(key)) {
      continue;
    }

    seen.add(key);
    unique.push(option);

    if (unique.length >= limit) {
      break;
    }
  }

  return unique;
}

