  function onCountingObjectPress(index: number, count: number, complete?: () => void) {
    setCountedObjectIndexes((current) => {
      if (current.includes(index)) {
        return current;
      }

      const next = [...current, index];
      speakText(getCountWords(count)[next.length - 1] ?? `${next.length}`);

      if (next.length >= count) {
        complete?.();
      }

      return next;
    });
  }

