const FRAMEWORK_STAGE_BY_PHASE: Record<ActiveLearningPhase, FrameworkStageLabel> = {
  Challenge: "PLAY",
  Discover: "LOOK",
  Explore: "TAP",
  Interact: "TRY",
  Mastery: "MASTERED",
  Practice: "CHOOSE",
  Progress: "PROGRESS",
  Reward: "STAR",
};

function getPublishedContentStageTypeForStep(
  step: ActiveLearningPhase
): ContentDraftStageType | null {
  if (step === "Discover") return "LOOK";
  if (step === "Explore") return "TAP";
  if (step === "Interact") return "TRY";
  if (step === "Practice") return "CHOOSE";
  if (step === "Challenge") return "PLAY";
  if (step === "Reward") return "REWARD";
  return null;
}

function getPublishedStageInstruction(
  content: unknown,
  stageType: ContentDraftStageType,
  fallback: string
) {
  const record = toPlainRecord(content);
  const stages = Array.isArray(record.stages) ? record.stages.map(toPlainRecord) : [];
  const stageRecord =
    stages.find((stage) => String(stage.stageType ?? stage.stageLabel ?? "") === stageType) ??
    record;
  const instruction = String(stageRecord.instruction ?? record.instruction ?? "").trim();

  return instruction || fallback;
}

function toPlainRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function getFrameworkStageForStep(
  topic: CurriculumTopic | undefined,
  step: ActiveLearningPhase
): FrameworkStageContent | undefined {
  const stageLabel = FRAMEWORK_STAGE_BY_PHASE[step];

  return topic?.frameworkStages?.find((stage) => stage.stage === stageLabel);
}

function getRendererLabel(renderer?: string | null) {
  if (!renderer) {
    return "Topic Renderer";
  }

  return renderer.replace(/Renderer$/, " Renderer");
}

function getQuestionChoices(stage?: FrameworkStageContent) {
  const question =
    stage?.independentQuestions?.[0] ??
    stage?.guidedQuestions?.[0];

  return stage?.choices ?? question?.choices ?? [];
}

function getQuestionAnswer(stage?: FrameworkStageContent, fallback = "") {
  return (
    stage?.correctAnswer ??
    stage?.independentQuestions?.[0]?.correctAnswer ??
    stage?.guidedQuestions?.[0]?.correctAnswer ??
    fallback
  );
}

function normalizeChoiceLabel(value: string) {
  return value.trim().toLowerCase().replace(/[^a-z0-9']+/g, " ").replace(/\s+/g, " ");
}

function areEquivalentChoiceLabels(left: string, right: string) {
  const normalizedLeft = normalizeChoiceLabel(left);
  const normalizedRight = normalizeChoiceLabel(right);

  if (!normalizedLeft || !normalizedRight) {
    return false;
  }

  if (normalizedLeft === normalizedRight) {
    return true;
  }

  const compactLeft = normalizedLeft.replace(/\s+/g, "");
  const compactRight = normalizedRight.replace(/\s+/g, "");

  if (compactLeft === compactRight) {
    return true;
  }

  const timeWords = new Set(["clock", "wall clock", "clock face"]);

  return timeWords.has(normalizedLeft) && timeWords.has(normalizedRight);
}

function uniqueChoiceLabels(values: string[], limit: number) {
  const seen = new Set<string>();
  const unique: string[] = [];

  values.forEach((value) => {
    const label = value.trim();
    const key = normalizeChoiceLabel(label);

    if (!label || seen.has(key)) {
      return;
    }

    seen.add(key);
    unique.push(label);
  });

  return unique.slice(0, limit);
}

function sanitizeCompetencyChoices(values: string[], correctAnswer: string, limit: number) {
  const choices = uniqueChoiceLabels(
    values.filter((value) =>
      areEquivalentChoiceLabels(value, correctAnswer) ||
      !isWeakCompetencyChoice(value)
    ),
    Math.max(values.length, limit + 3)
  );
  const clean: string[] = [];

  choices.forEach((choice) => {
    const isCorrectEquivalent = areEquivalentChoiceLabels(choice, correctAnswer);

    if (
      isCorrectEquivalent &&
      clean.some((existing) => areEquivalentChoiceLabels(existing, correctAnswer))
    ) {
      return;
    }

    if (!isCorrectEquivalent && clean.some((existing) => areEquivalentChoiceLabels(existing, choice))) {
      return;
    }

    clean.push(choice);
  });

  const repaired = repairChoicesForTarget({
    choiceLimit: limit,
    choices: clean,
    correctAnswer,
    distractorPool: values,
    targetConcept: correctAnswer,
  });

  return (repaired.activity.choices ?? [])
    .map((choice) =>
      typeof choice === "string"
        ? choice
        : choice.label ?? choice.text ?? choice.title ?? choice.concept ?? choice.id ?? ""
    )
    .slice(0, limit);
}

function isWeakCompetencyChoice(value: string) {
  const label = normalizeChoiceLabel(value);

  return (
    label === ["random", "order"].join(" ") ||
    label === ["guess", "ing"].join("") ||
    label === ["color", "only"].join(" ") ||
    label === ["size", "only"].join(" ")
  );
}

function getShortLearnerLabel(value: string) {
  const [firstPart] = value.split(":");

  return firstPart.replace(/\s+simulation$/i, "").trim();
}

function toGrade1DisplayLabel(value: string) {
  return getShortLearnerLabel(value)
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function getGrade1FriendlyChoiceLabel(value: string) {
  const label = toGrade1DisplayLabel(value);
  const replacements: Record<string, string> = {
    "Action Words": "Actions",
    "Describing Words": "Describing",
    "Math Challenge": "Math Review",
    "Number Sentences": "Number Sentence",
    "Shape Challenge": "Shape Match",
    "Shape Properties": "Shape Parts",
    "Subtraction": "Take Away",
  };

  return replacements[label] ?? label;
}

