function getGrade1SemanticAssetKey(value: string) {
  const normalized = normalizeChoiceLabel(getShortLearnerLabel(value));

  return GRADE1_SEMANTIC_ASSET_KEYS[normalized] ?? value;
}

function getBatibotGradeForWorld(worldId: string) {
  if (worldId.startsWith("grade1-")) return "grade1";
  if (worldId.startsWith("grade2-")) return "grade2";
  if (worldId.startsWith("grade3-")) return "grade3";
  if (worldId.startsWith("kindergarten-")) return "kindergarten";
  if (worldId.startsWith("preschool-")) return "preschool";

  return "shared";
}

function getStandardChoiceGradeLevel(worldId: string): StandardChoiceGradeLevel {
  if (worldId.startsWith("grade3-")) return "grade3";
  if (worldId.startsWith("grade2-")) return "grade2";
  if (worldId.startsWith("kindergarten-")) return "kindergarten";
  if (worldId.startsWith("preschool-")) return "preschool";

  return "grade1";
}

function getSymbolFallback(label: string, lines?: string[]) {
  const normalized = normalizeChoiceLabel(`${label} ${(lines ?? []).join(" ")}`);

  if (normalized.includes("greater")) return ">";
  if (normalized.includes("less")) return "<";
  if (normalized.includes("equal")) return "=";
  if (normalized.includes("minus") || normalized.includes("subtract")) return "-";
  if (normalized.includes("multiply")) return "x";
  if (normalized.includes("divide")) return "/";
  if (normalized.includes("half")) return "1/2";
  if (normalized.includes("third")) return "1/3";
  if (normalized.includes("quarter") || normalized.includes("fourth")) return "1/4";
  if (normalized.includes("plus") || normalized.includes("add")) return "+";

  return lines?.[0] ?? label;
}

function getGrade1ShapeSymbol(label: string) {
  const normalized = normalizeChoiceLabel(label);

  if (normalized.includes("circle")) return "○";
  if (normalized.includes("square") || normalized.includes("cube")) return "□";
  if (normalized.includes("triangle") || normalized.includes("cone")) return "△";
  if (normalized.includes("rectangle")) return "▭";
  if (normalized.includes("sphere")) return "●";
  if (normalized.includes("cylinder")) return "▯";
  if (normalized.includes("side")) return "—";
  if (normalized.includes("corner")) return "⌜";
  if (normalized.includes("curve")) return "⌒";
  if (normalized.includes("face")) return "▣";

  return undefined;
}

function getTapRevealParts(rawFact: string, fallbackLabel: string) {
  const [labelPart, ...revealParts] = rawFact.split("|");
  const label = revealParts.length ? labelPart.trim() : getShortLearnerLabel(labelPart || fallbackLabel);
  const fact = (revealParts.length ? revealParts.join("|") : rawFact).trim();

  return {
    fact,
    label: label || fallbackLabel,
  };
}

function getTopicFrameworkActivityData({
  fallback,
  step,
  topic,
  topicLabel,
}: {
  fallback: AdvancedActivityData;
  step: ActiveLearningPhase;
  topic?: CurriculumTopic;
  topicLabel: string;
}): AdvancedActivityData {
  const stage = getFrameworkStageForStep(topic, step);
  const playStage = getFrameworkStageForStep(topic, "Challenge");
  const content = topic?.batibotContent;
  const renderer = getTopicRendererName(topic) ?? stage?.renderer ?? fallback.rendererLabel;
  const examples =
    content?.examples?.map((example) =>
      example.sentence ? `${example.label}: ${example.sentence}` : example.label
    ) ?? [];
  const exampleLabels = content?.examples?.map((example) => example.label) ?? [];
  const nonExamples = content?.nonExamples?.map((item) => `${item.label} is not ${topicLabel}.`) ?? [];
  const vocabulary = content?.vocabularyBank?.map((entry) => `${entry.word}: ${entry.meaning}`) ?? [];
  const knowledgeItems =
    content?.knowledgeUnits?.map((unit) => unit.teachingPoint) ?? [];
  const exploreFacts =
    stage?.discoveryContent?.map((fact, index) =>
      getTapRevealParts(fact, `${topicLabel} ${index + 1}`)
    ) ??
    content?.examples?.map((example) => ({
      fact: example.sentence || `${example.label} shows ${topicLabel}.`,
      label: example.label,
    })) ??
    [];
  const stageChoices = getQuestionChoices(stage);
  const answer = getQuestionAnswer(stage, exampleLabels[0] ?? topicLabel);
  const choices = stageChoices.length
    ? sanitizeCompetencyChoices(stageChoices, answer, 6)
    : sanitizeCompetencyChoices(
        [...exampleLabels, ...fallback.choices].filter(Boolean),
        answer,
        6
      );
  const applicationActivity = playStage?.applicationActivity ?? stage?.applicationActivity;
  const manipulatives = stage?.manipulatives ?? playStage?.manipulatives ?? [];
  const model = Array.from(
    new Set([
      ...manipulatives,
      ...(stage?.visualContent ?? []),
      ...exampleLabels,
      ...fallback.model,
    ].filter(Boolean))
  ).slice(0, 6);

  return {
    ...fallback,
    actionLabel:
      applicationActivity?.type ??
      applicationActivity?.name ??
      stage?.learnerAction ??
      fallback.actionLabel,
    answer,
    applicationName:
      applicationActivity?.name ??
      applicationActivity?.type ??
      content?.behaviorProfile?.allowedPlayActivities?.[0] ??
      fallback.applicationName,
    choices: choices.length ? choices : fallback.choices,
    discover:
      stage?.teachingScript ??
      stage?.content ??
      content?.knowledge ??
      fallback.discover,
    evidence: stage?.evidenceSentences ?? fallback.evidence,
    exampleCards: uniqueChoiceLabels(
      [
        ...(stage?.manipulatives ?? []),
        ...exampleLabels,
        ...fallback.model,
      ],
      5
    ).map((item, index) => getTapRevealParts(item, `${topicLabel} ${index + 1}`).label),
    exploreFacts,
    feedbackCorrect: stage?.feedbackCorrect ?? fallback.feedbackCorrect,
    feedbackWrong: stage?.feedbackWrong ?? fallback.feedbackWrong,
    knowledgeItems,
    masteryItems:
      stage?.masteryConditions ??
      content?.masteryRules?.conditions ??
      fallback.masteryItems,
    model: model.length ? model : fallback.model,
    nonExamples,
    prompt:
      stage?.questionText ??
      stage?.instruction ??
      stage?.content ??
      fallback.prompt,
    rendererLabel: getRendererLabel(renderer),
    scaffold:
      stage?.learnerAction ??
      stage?.interaction ??
      stage?.uiBehavior ??
      fallback.scaffold,
    stageContent: stage?.content,
    stageInstruction: stage?.instruction,
    vocabulary,
    visual:
      stage?.imagePrompt ??
      stage?.visualContent?.[0] ??
      examples[0] ??
      fallback.visual,
  };
}

function getCompactActivityLabel(value?: string) {
  return value?.replace(/\s+Simulation$/i, "").trim() || "Topic Activity";
}

function getMasteryChecklist(data: AdvancedActivityData, topicLabel: string) {
  const activity = getCompactActivityLabel(data.applicationName ?? data.actionLabel);
  const masteryItems = data.masteryItems?.filter(Boolean).slice(0, 4);

  if (masteryItems?.length) {
    return masteryItems;
  }

  return [
    `Recognized ${topicLabel}`,
    `${activity}`,
    `Completed ${topicLabel} challenge`,
    "Earned mastery",
  ];
}

function getProgressRows(
  topics: CurriculumTopic[],
  activeTopicIndex: number,
  masteredTopics: string[]
) {
  return topics.map((item, index) => {
    const mastered = masteredTopics.includes(item.title);
    const status: TopicProgressStatus =
      mastered ? "completed" : index === activeTopicIndex ? "current" : "locked";

    return {
      id: `${item.title}-${index}`,
      label: getTopicLabel(item),
      status,
    };
  });
}

