type Grade1ImageWordPair = { imageLabel: string; word: string };
type Grade1WordTapCard = {
  id: string;
  imageKey?: string;
  label: string;
  meaning: string;
};
type Grade1VisualTapCard = {
  id: string;
  label: string;
  meaning: string;
  title?: string;
  visualLines?: string[];
};
type Grade1ReadingQuestCard = {
  imageLabel: string;
  label: string;
  meaning: string;
};
type Grade1ReadingQuestLesson = {
  chooseAnswer: string;
  chooseChoices: string[];
  chooseImageLabel?: string;
  choosePrompt: string;
  lookCards: Grade1ReadingQuestCard[];
  playSequence?: Grade1ReadingQuestCard[];
  tapCards: Grade1ReadingQuestCard[];
  tryAnswer: string;
  tryChoices: string[];
};
type Grade1ActivityRound = { answer: string; choices: string[]; prompt: string };
type Grade1ClockRound = { hour: number; prompt: string };
type Grade1PlayActivityConfig =
  | {
      type: "sort";
      title: string;
      instruction: string;
      categories: string[];
      pairs: Grade1ActivityPair[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "match";
      title: string;
      instruction: string;
      pairs: Grade1ActivityPair[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "sequence";
      title: string;
      instruction: string;
      sequence: string[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "hunt";
      title: string;
      instruction: string;
      targets: string[];
      distractors: string[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "image-word-drag";
      title: string;
      instruction: string;
      pairs: Grade1ImageWordPair[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "clock";
      title: string;
      instruction: string;
      rounds: Grade1ClockRound[];
      success: string;
      hint: string;
      visualItems?: string[];
    }
  | {
      type: "rounds";
      title: string;
      instruction: string;
      rounds: Grade1ActivityRound[];
      success: string;
      hint: string;
      visualItems?: string[];
    };

