function NumberChoiceGrid({
  answer,
  choiceSeed,
  choices,
  completed,
  locked = false,
  maxChoices = 2,
  onAnswer,
  selectedChoice,
  showCorrectAnswer = true,
  showWrongAnswer = true,
  wrongTrigger,
}: {
  answer: number;
  choiceSeed?: string;
  choices: number[];
  completed: boolean;
  locked?: boolean;
  maxChoices?: number;
  meta: { accent: string; badge: string; title: string };
  onAnswer: (correct: boolean, choice: number) => void;
  selectedChoice?: string | null;
  showCorrectAnswer?: boolean;
  showWrongAnswer?: boolean;
  wrongTrigger: number;
}) {
  const choiceCount = getAllowedChoiceCount(maxChoices);
  const choicePool = Array.from(
    new Set([
      answer,
      ...choices,
      ...getNearbyNumberChoices(answer),
    ])
  )
    .filter((choice) => Number.isFinite(choice) && choice > 0)
    .slice(0, choiceCount);
  const visibleChoices = getStableShuffledItems(
    choiceCount === 2 ? getTwoNumberChoices(answer, choicePool) : choicePool,
    choiceSeed ?? `number-choice-${answer}-${choices.join("-")}-${choiceCount}`
  );
  const standardChoices: StandardChoice[] = visibleChoices.map((choice) => ({
    id: `${choice}`,
    label: `${choice}`,
  }));
  const selectedId = selectedChoice ? `${selectedChoice}` : null;

  return (
    <Shakeable trigger={completed && showWrongAnswer ? wrongTrigger : 0}>
      <StandardChoiceGrid
        choices={standardChoices}
        contentType="text"
        correctIds={completed && showCorrectAnswer ? [`${answer}`] : []}
        disabled={locked}
        gradeLevel="kindergarten"
        onSelect={(choiceId) => onAnswer(Number(choiceId) === answer, Number(choiceId))}
        selectedIds={selectedId ? [selectedId] : []}
        wrongIds={
          completed && showWrongAnswer && selectedId && selectedId !== `${answer}`
            ? [selectedId]
            : []
        }
      />
    </Shakeable>
  );
}

function ConceptActivityVisual({
  completed = false,
  labelMode = "always",
  lesson,
  locked = false,
  meta,
  onChoice,
  selectedChoiceId,
  showCorrectAnswer = true,
  showWrongAnswer = true,
  wrongChoiceId,
  wrongTrigger = 0,
}: {
  completed?: boolean;
  labelMode?: "always" | "feedback" | "hidden";
  lesson: PreschoolConceptLesson;
  locked?: boolean;
  meta: { accent: string; badge: string; title: string };
  onChoice?: (correct: boolean, choiceId: string) => void;
  selectedChoiceId?: string | null;
  showCorrectAnswer?: boolean;
  showWrongAnswer?: boolean;
  wrongChoiceId?: string | null;
  wrongTrigger?: number;
}) {
  const showLabels = labelMode === "always" || (labelMode === "feedback" && completed);

  if (lesson.kind === "pattern" && lesson.pattern) {
    return (
      <View style={lessonStyles.conceptVisualWrap}>
        <PatternStrip completed={completed} lesson={lesson} meta={meta} showLabels={showLabels} />
        {onChoice ? (
          <AnimatedButton
            pressedScale={1.04}
            style={[
              lessonStyles.patternMissingButton,
              completed && showCorrectAnswer && lessonStyles.successCard,
            ]}
            disabled={locked}
            onPress={() => onChoice(true, lesson.pattern?.answerId ?? lesson.answerLabel)}
          >
            <Text style={[lessonStyles.patternMissingButtonText, { color: meta.accent }]}>
              Missing tile
            </Text>
          </AnimatedButton>
        ) : null}
      </View>
    );
  }

  return (
    <View style={lessonStyles.conceptSceneRow}>
      {lesson.sceneItems.map((item) => {
        const correct = lesson.correctItemIds.includes(item.id);
        const selectedWrong = completed && showWrongAnswer && selectedChoiceId === item.id && !correct;
        const trigger = wrongChoiceId === item.id || (!wrongChoiceId && !correct)
          ? wrongTrigger
          : 0;
        const content = (
          <View
            style={[
              lessonStyles.conceptSceneCard,
              (item.role === "more" || item.role === "less" || item.role === "equal") && lessonStyles.conceptQuantityCard,
              (item.role === "tall" || item.role === "short") && lessonStyles.conceptHeightCard,
              correct && completed && showCorrectAnswer && lessonStyles.successCard,
              selectedWrong && lessonStyles.wrongChoiceCard,
            ]}
          >
            <ConceptSceneItemView item={item} />
            {showLabels ? (
              <Text style={lessonStyles.conceptItemLabel}>{item.label}</Text>
            ) : null}
            {showLabels && item.valueLabel ? (
              <Text style={lessonStyles.conceptValueLabel}>{item.valueLabel}</Text>
            ) : null}
            {correct && completed && showCorrectAnswer ? (
              <View style={lessonStyles.tapCheckBadge}>
                <Ionicons name="checkmark" size={23} color="#FFFFFF" />
              </View>
            ) : null}
          </View>
        );

        return (
          <Shakeable key={item.id} trigger={trigger}>
            {onChoice ? (
              <AnimatedButton
                pressedScale={1.04}
                disabled={locked}
                onPress={() => onChoice(correct, item.id)}
              >
                {content}
              </AnimatedButton>
            ) : (
              content
            )}
          </Shakeable>
        );
      })}
    </View>
  );
}

